// THE SHOT LIST — every shot starts at an anchor in the narration:
//   'L012' line start · 'L012:bread' word start · 'L012>' line end · '+1.2' after the previous shot start · numbers = seconds
// cam: [x, y, z] or a move [x0, y0, z0, x1, y1, z1] (layer coords of the characters' ground). cast: rigs with keyframes (time relative to the shot start, or an anchor).
// fx: sw (sound word) · bub (speech bubble) · think · label (+ on/part for exact targets) · pop · poof · notes · drops · crumbs · hearts · sparkle · speed · prop · door
// tr: page | wipe | mist (between places); cuts inside a place.   sfx: [time, type, gain] for the mixer.
const SC = name => ({ scene: true, name });
const C = (id, x, y, o = {}, kf) => Object.assign({ id, x, y }, o, kf ? { kf } : {});
const HT = 300, HP = 165, HK = 290, HQ = 275;
const MED = (x, y, h, dx = 0, k = 1) => [x + dx, y - h * .52, .6 * 1080 / h * k];
const CU = (x, y, h, dx = 0, k = 1) => [x + dx, y - h * .76, .95 * 1080 / h * k];
const IN = (c, k = 1.1, dx = 0, dy = 0) => [c[0], c[1], c[2], c[0] + dx, c[1] + dy, c[2] * k];
const OUT = (c, k = 1.1, dx = 0, dy = 0) => [c[0], c[1], c[2], c[0] + dx, c[1] + dy, c[2] / k];
const PAN = (c, dx, dy = 0, k = 1) => [c[0], c[1], c[2], c[0] + dx, c[1] + dy, c[2] * k];

